import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Teoria della probabilità","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/l_calcolo-delle-probabilita/lc/lc.md","filePath":"lezioni/l_calcolo-delle-probabilita/lc/lc.md"}`),a={name:`lezioni/l_calcolo-delle-probabilita/lc/lc.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="teoria-della-probabilita" tabindex="-1">Teoria della probabilità <a class="header-anchor" href="#teoria-della-probabilita" aria-label="Permalink to “Teoria della probabilità”">​</a></h1><p>Ora possiamo iniziare la teoria della probabilità: grosso modo possiamo distinguere tre teorie diverse: la probabilità classica, la teoria frequentista (o probabilità statistica) e la probabilità soggettiva; vedremo di superare i loro limiti considerando poi la definizione assiomatica di probabilità che comprende le altre definizioni come casi particolari.</p><blockquote><p>Per seguire l&#39;argomento è necessario conoscere bene la teoria degli insiemi.</p></blockquote><blockquote><p>Nel biennio ed in parecchie scuole anche del triennio è sufficiente limitare il calcolo delle probabilità alla probabilità classica con qualche semplice cenno alla frequentista ed alla soggettiva; in tal caso puoi saltare la probabilità assiomatica.</p><p>In altre invece nel triennio è richiesta la probabilità assiomatica considerando le altre probabilità come casi particolari; in questo caso devi fare tutto il capitolo sulle <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>4</mn></mrow><annotation encoding="application/x-tex">4</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">4</span></span></span></span> probabilità.</p></blockquote><p>Premettiamo anche alcune nozioni comuni a tutti i tipi di probabilità:</p><ul><li>Introduzione; concetto di evento</li><li>Spazio delle probabilità ed eventi</li><li>Operazioni sugli eventi</li><li>Probabilità classica</li><li>Probabilità statistica (o frequentista)</li><li>Probabilità soggettiva</li><li>Definizione assiomatica di probabilità</li><li>Teoremi</li></ul>`,6)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};